// Test harness: jsdom globals first, then the real App rendered into the DOM.
import { JSDOM } from 'jsdom';

const dom = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>', {
  url: 'http://localhost/',
  pretendToBeVisual: true,
});
const w = dom.window;
for (const key of ['document', 'HTMLElement', 'Element', 'Node', 'getComputedStyle', 'MutationObserver', 'requestAnimationFrame', 'cancelAnimationFrame', 'Event', 'MouseEvent', 'KeyboardEvent', 'SVGElement']) {
  if (w[key] !== undefined) globalThis[key] = w[key];
}
globalThis.window = w;
globalThis.ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
globalThis.matchMedia = () => ({ matches: false, media: '', addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {} });
globalThis.IS_REACT_ACT_ENVIRONMENT = true;

import { createRoot } from 'react-dom/client';
import { act } from 'react-dom/test-utils';
import { App } from '/home/sandbox/workspace/src/App.tsx';

const errors = [];
const origError = console.error;
console.error = (...args) => { errors.push(args.map(String).join(' ').slice(0, 300)); };

const root = createRoot(document.getElementById('root'));
await act(async () => { root.render(<App />); });

